#include <Servo.h>

const int FSR = A0;
const int BELL = 8;
const long PULLDOWN = 10000;  // must match the resistor on the breadboard
Servo needle;

int best = 0;              // the hardest hit so far
unsigned long bestAt = 0;  // when it happened
bool rung = false;

void setup() {
  needle.attach(9);
  Serial.begin(9600);
}

void loop() {
  int force = analogRead(FSR);  // harder press, higher reading

  // hold the best hit for a moment, then follow the pad again
  if (force >= best || millis() - bestAt > 1500) {
    best = force;
    bestAt = millis();
  }
  needle.write(map(best, 0, 1023, 0, 180));

  if (best > 880 && !rung) {
    tone(BELL, 1568, 400);  // G6 for 400 ms
    rung = true;
  } else if (best < 880 - 100) {
    rung = false;
  }

  if (force > 10) {
    // work back from the divider to the sensor's resistance
    long ohms = PULLDOWN * (1023L - force) / force;
    Serial.print(force);
    Serial.print("  ");
    Serial.print(ohms);
    Serial.println(" ohms");
  }
  delay(20);
}
